.list{display:flex; flex-direction:column}
.list-item{display:flex; align-items:center; justify-content:space-between; gap:var(--space-4); padding:.75rem var(--space-5); border-top:1px solid var(--stroke2)}
.list-item:hover{background: rgba(255,255,255,.03)}
.list-main{display:flex; align-items:center; gap:var(--space-3)}
.avatar{
  width:32px; height:32px; border-radius:12px;
  background: rgba(41,98,255,.18);
  border:1px solid rgba(41,98,255,.25);
  display:grid; place-items:center;
  font-weight:900; color: rgba(255,255,255,.9);
}

/* Footer */
