}
.hero-grid{display:grid; grid-template-columns: 1.35fr .65fr; gap:var(--space-4)}
@media (max-width: 980px){ .hero-grid{grid-template-columns: 1fr} }
.hero h1{margin:0; font-size:2.1rem; line-height:1.1; letter-spacing:-.02em}
.hero p{margin:.65rem 0 0; color:var(--muted); max-width:72ch}
.hero-cta{margin-top:1.05rem; display:flex; gap:.6rem; flex-wrap:wrap}
.hero-metrics{display:grid; gap:var(--space-3)}
.metric{
  padding: var(--space-4);
  border-radius: var(--radius);
  border:1px solid var(--stroke2);
  background: linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
}
.metric-k{color:var(--muted); font-size:.78rem; font-weight:800; text-transform:uppercase; letter-spacing:.08em}
.metric-v{font-variant-numeric: tabular-nums; font-weight:900; font-size:1.15rem; margin-top:.35rem}

/* Chart page */
.terminal{
  display:grid;
  grid-template-columns: 320px 1fr 360px;
  gap: var(--space-4);
}
@media (max-width: 1200px){ .terminal{grid-template-columns: 300px 1fr} .right-rail{display:none} }
@media (max-width: 980px){ .terminal{grid-template-columns: 1fr} .watchlist{display:none} }

.toolbar{
  display:flex; align-items:center; justify-content:space-between;
  gap: var(--space-4);
  padding: .7rem var(--space-5);
}
.toolbar .left, .toolbar .right{display:flex; align-items:center; gap:.55rem; flex-wrap:wrap}
.chip{border:1px solid var(--stroke2); background: rgba(255,255,255,.04); color:var(--muted); padding:.35rem .55rem; border-radius:999px; font-weight:800; font-size:.78rem}

.watchlist .card-head{padding: var(--space-4) var(--space-5)}
.accordion-section{border-top:1px solid var(--stroke2)}
.accordion-btn{
  width:100%; display:flex; align-items:center; justify-content:space-between;
  gap:var(--space-3);
  padding: .7rem var(--space-5);
  background: transparent; border:0; color:var(--text); cursor:pointer;
  font-weight:900;
}
.accordion-btn span{color:var(--muted); font-weight:800; font-size:.82rem}
.accordion-panel{padding: 0 var(--space-5) var(--space-4)}
.accordion-panel[hidden]{display:none}

.wl-row{display:grid; grid-template-columns: 1fr 1fr 1fr; gap:.65rem; padding:.45rem .35rem; border-radius:10px}
.wl-row:hover{background: rgba(255,255,255,.04)}
.wl-sym{font-family:var(--font-mono); font-weight:900}
.wl-last{font-variant-numeric:tabular-nums; text-align:right}
.wl-chg{font-variant-numeric:tabular-nums; text-align:right; color:var(--muted)}
.wl-chg.good{color: color-mix(in oklab, var(--good) 80%, white 10%)}
.wl-chg.bad{color: color-mix(in oklab, var(--bad) 85%, white 10%)}

.chart-area{padding:0}
.chart-top{display:flex; align-items:center; justify-content:space-between; gap:var(--space-4); padding: var(--space-4) var(--space-5); border-bottom:1px solid var(--stroke2)}
.symbol-line{display:flex; align-items:baseline; gap:.6rem; flex-wrap:wrap}
.symbol{font-family:var(--font-mono); font-weight:950; font-size:1.05rem}
.company{color:var(--muted); font-weight:700}
.exchange{color:var(--faint); font-size:.86rem}

.timeframes{display:flex; gap:.35rem; flex-wrap:wrap}
.tf{padding:.38rem .55rem; border-radius:10px; border:1px solid var(--stroke2); background: rgba(255,255,255,.04); color:var(--muted); font-weight:900; font-size:.78rem; cursor:pointer}
.tf[aria-pressed="true"]{background: rgba(41,98,255,.18); color:var(--text); border-color: rgba(41,98,255,.28)}

.candles{
  height: 430px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.01)),
    radial-gradient(900px 420px at 20% 0%, rgba(41,98,255,.14), transparent 60%),
    radial-gradient(700px 420px at 90% 30%, rgba(0,208,201,.10), transparent 60%);
  border-bottom-left-radius: var(--radius);
  border-bottom-right-radius: var(--radius);
  position:relative;
  overflow:hidden;
}
.gridlines{position:absolute; inset:0; background-image: linear-gradient(to right, rgba(255,255,255,.05) 1px, transparent 1px), linear-gradient(to bottom, rgba(255,255,255,.05) 1px, transparent 1px); background-size: 80px 60px; opacity:.28}
.candle-svg{position:absolute; inset:0}
.chart-footer{display:flex; align-items:center; justify-content:space-between; gap:var(--space-4); padding: .75rem var(--space-5)}

/* Lists */
.list{display:flex; flex-direction:column}
.list-item{display:flex; align-items:center; justify-content:space-between; gap:var(--space-4); padding:.75rem var(--space-5); border-top:1px solid var(--stroke2)}
.list-item:hover{background: rgba(255,255,255,.03)}
.list-main{display:flex; align-items:center; gap:var(--space-3)}
.avatar{
  width:32px; height:32px; border-radius:12px;
  background: rgba(41,98,255,.18);
  border:1px solid rgba(41,98,255,.25);
  display:grid; place-items:center;
  font-weight:900; color: rgba(255,255,255,.9);
}

/* Footer */
.footer{padding: 1.2rem 0 2.2rem; color:var(--muted)}
.footer-grid{display:grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: var(--space-4)}
.footer h4{margin:.2rem 0 .55rem; font-size:.8rem; text-transform:uppercase; letter-spacing:.08em; color:var(--faint)}
.footer a{display:block; padding:.2rem 0; color:var(--muted)}
.footer a:hover{color:var(--text)}
@media (max-width: 980px){ .footer-grid{grid-template-columns: repeat(2, minmax(0, 1fr))} }

/* Motion */
[data-animate]{
  animation: fadeUp .5s ease-out both;
}
@keyframes fadeUp{from{opacity:0; transform:translateY(10px)} to{opacity:1; transform:translateY(0)}}

/* A11y */
.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); border:0}
